package com.governai.decision; import com.governai.organization.RiskLevel; import tools.jackson.databind.JsonNode; import java.time.OffsetDateTime; import java.util.UUID; public record DecisionRequestResponse(UUID id,UUID organizationId,UUID requestedBy,String question,String purpose,String provider,String dataType,JsonNode additionalContext,String jurisdiction,RiskLevel riskLevel,DecisionStatus status,boolean humanReviewRequired,UUID assignedReviewer,OffsetDateTime createdAt,OffsetDateTime updatedAt){public static DecisionRequestResponse from(DecisionRequest d){return new DecisionRequestResponse(d.getId(),d.getOrganizationId(),d.getRequestedBy(),d.getQuestion(),d.getPurpose(),d.getProvider(),d.getDataType(),d.getAdditionalContext(),d.getJurisdiction(),d.getRiskLevel(),d.getStatus(),d.isHumanReviewRequired(),d.getAssignedReviewer(),d.getCreatedAt(),d.getUpdatedAt());}}
